/bin/zsh -lc 'tmp=$(mktemp ./.main.go.XXXXXX) && cat > "$tmp" <<'"'EOF'
package main

import (
	\"log\"
	\"math/rand\"
	\"os\"
	\"text/template\"
)

func main() {
	tmpl := template.Must(template.New(\"greeting\").Parse(\"Hello World {{.}}\\n\"))
	if err := tmpl.Execute(os.Stdout, rand.Int()); err "'!= nil {
		log.Fatal(err)
	}
}
EOF
sync "$tmp" && mv "$tmp" main.go'

